<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hesap oluştur</title><style>body{margin:0;background:#f4f7f4;font-family:system-ui;color:#243129;min-height:100vh;display:grid;place-items:center}.card{background:white;width:min(430px,calc(100% - 32px));padding:30px;border-radius:18px;box-shadow:0 12px 40px #203c2b12}h1{margin:0 0 8px}.muted{color:#6c796f;font-size:14px}label{display:block;margin:16px 0 6px;font-size:13px;font-weight:700}input{width:100%;box-sizing:border-box;padding:13px;border:1px solid #dce5de;border-radius:9px;font:inherit}button{width:100%;margin-top:20px;padding:14px;border:0;border-radius:10px;background:#176b50;color:white;font-weight:750;font-size:15px}.error{background:#fff0ef;color:#a02b27;padding:11px;border-radius:8px}.card a{color:#176b50}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="card"><h1>Hesap oluştur</h1><p class="muted">Rezervasyonlarınızı takip etmek için ücretsiz misafir hesabı açın.</p><?php if(!empty($error)): ?><div class="error"><?= e($error) ?></div><?php endif; ?><form method="post" action="/register"><?= csrf_field() ?><label>Adınız / kullanıcı adınız</label><input name="username" required minlength="3" maxlength="80" autocomplete="username"><label>E-posta</label><input name="email" type="email" required autocomplete="email"><label>Şifre (en az 10 karakter)</label><input name="password" type="password" required minlength="10" autocomplete="new-password"><label>Şifre tekrarı</label><input name="password_confirm" type="password" required minlength="10" autocomplete="new-password"><button type="submit">Hesap oluştur</button></form><p class="muted">Zaten hesabınız var mı? <a href="/login">Giriş yapın</a></p><a href="/">Ana sayfaya dön</a></main></body></html>